import type { SelectKeys, ExcludeKeys, FilterIn, FilterOut } from '../Filter'

import toolbelt = require('ts-toolbelt')
const { Test } = toolbelt
namespace Test {
    export type Pass = toolbelt.Test.Pass
    export type Fail = toolbelt.Test.Fail
}

type Properties = {
    A1?: number
    A2: 123
    B1?: string
    B2: 'Hello'
    C1?: boolean
    C2: true
    D1?: number | undefined
    D2: 123 | undefined
    E1?: string | undefined
    E2: 'Hello' | undefined
    F1?: boolean | undefined
    F2: true | undefined
}

type TestA1 = SelectKeys<Required<Properties>, number>
type TestA1b = SelectKeys<Properties, number>
type TestA1c = SelectKeys<Properties, number, 'invert'>
type TestA2 = SelectKeys<Properties, 123>
type TestA2b = SelectKeys<Properties, 123, 'invert'>
type TestB1 = SelectKeys<Required<Properties>, string>
type TestB1b = SelectKeys<Properties, string>
type TestB2 = SelectKeys<Properties, 'Hello'>
type TestC1 = SelectKeys<Required<Properties>, boolean>
