type TestE2 = SelectKeys<Properties, 'Hello' | undefined>
type TestF1 = SelectKeys<Properties, boolean | undefined>
type TestF2 = SelectKeys<Properties, true | undefined>
type TestG1 = SelectKeys<Required<Properties>, NonNullable<unknown>>
type TestG1b = SelectKeys<Properties, NonNullable<unknown>>
type TestG2 = SelectKeys<Properties, unknown>
type TestG3 = SelectKeys<Properties, undefined>

Test.checks([
    Test.check<TestA1, 'A1' | 'A2', Test.Pass>(),
    Test.check<TestA1b, 'A2', Test.Pass>(),
    Test.check<TestA1c, 'A1' | 'D1', Test.Pass>(),
    Test.check<TestA2, 'A2', Test.Pass>(),
    Test.check<TestA2b, 'A1' | 'A2' | 'D1' | 'D2', Test.Pass>(),
    Test.check<TestB1, 'B1' | 'B2', Test.Pass>(),
    Test.check<TestB1b, 'B2', Test.Pass>(),
    Test.check<TestB2, 'B2', Test.Pass>(),
    Test.check<TestC1, 'C1' | 'C2', Test.Pass>(),
    Test.check<TestC1b, 'C2', Test.Pass>(),
    Test.check<TestC2, 'C2', Test.Pass>(),
    Test.check<TestD1, 'D1' | 'D2' | 'A1' | 'A2', Test.Pass>(),
    Test.check<TestD2, 'D2' | 'A2', Test.Pass>(),
    Test.check<TestE1, 'E1' | 'E2' | 'B1' | 'B2', Test.Pass>(),
    Test.check<TestE2, 'E2' | 'B2', Test.Pass>(),
    Test.check<TestF1, 'F1' | 'F2' | 'C1' | 'C2', Test.Pass>(),
    Test.check<TestF2, 'F2' | 'C2', Test.Pass>(),
    Test.check<TestG1, 'A1' | 'A2' | 'B1' | 'B2' | 'C1' | 'C2', Test.Pass>(),
    Test.check<TestG1b, 'A2' | 'B2' | 'C2', Test.Pass>(),
    Test.check<TestG2, 'A1' | 'A2' | 'B1' | 'B2' | 'C1' | 'C2' | 'D1' | 'D2' | 'E1' | 'E2' | 'F1' | 'F2', Test.Pass>(),
    Test.check<TestG3, never, Test.Pass>(),
])

